});

import test from 'ava';
import ky, {HTTPError, NetworkError} from '../source/index.js';
import {createHttpTestServer} from './helpers/create-http-test-server.js';
import {parseRawBody} from './helpers/parse-body.js';

// Fetch §4.5 steps 12 and 14 specify method rewriting and body replay; RFC 9110 §§15.4.2–15.4.4, 15.4.8–15.4.9 define these statuses.
// https://fetch.spec.whatwg.org/#http-redirect-fetch
for (const [status, method, redirectedMethod] of [
	[301, 'POST', 'GET'],
	[302, 'POST', 'GET'],
	[303, 'POST', 'GET'],
	[303, 'PUT', 'GET'],
	[301, 'PUT', 'PUT'],
	[302, 'PATCH', 'PATCH'],
	[307, 'POST', 'POST'],
	[308, 'PUT', 'PUT'],
] as const) {
	test(`${status} redirects ${method} as ${redirectedMethod} with the expected body and headers`, async t => {
		const server = await createHttpTestServer(t, {bodyParser: false});
		const body = 'redirect payload';
		const requests: Array<{method: string; body: string}> = [];
		const bodyHeaders = {
			'content-type': 'text/plain',
			'content-encoding': 'identity',
			'content-language': 'en',
			'content-location': '/representation',
		};
		server.all('/start', async (request, response) => {
			requests.push({method: request.method, body: await parseRawBody(request)});
			response.writeHead(status, {location: '/destination'}).end();
		});
		server.all('/destination', async (request, response) => {
			requests.push({method: request.method, body: await parseRawBody(request)});
			response.json(request.headers);
		});

		const response = await ky(`${server.url}/start`, {
			method,
			body,
			headers: {...bodyHeaders, 'x-preserved': 'yes'},
			retry: 0,
		});
		const headers = await response.json<Record<string, string>>();

		}

		// RFC 9110 §15.4 requires removing content-specific headers when switching to GET.
		t.is(headers['content-length'], redirectedMethod === 'GET' ? undefined : String(body.length));
		t.is(response.url, `${server.url}/destination`);
		t.true(response.redirected);
	});
}

// Fetch §4.5 step 12 excludes both GET and HEAD from the 303 rewrite.
for (const method of ['GET', 'HEAD'] as const) {
	test(`303 preserves ${method}`, async t => {
		const server = await createHttpTestServer(t);
		const methods: string[] = [];
		server.all('/start', (request, response) => {
			methods.push(request.method);
			response.writeHead(303, {location: '/destination'}).end();
		});
		server.all('/destination', (request, response) => {
			methods.push(request.method);
			response.set('x-method', request.method).end('destination');
		});

		const response = await ky(`${server.url}/start`, {method, retry: 0});
		t.deepEqual(methods, [method, method]);
		t.is(response.headers.get('x-method'), method);
		t.is(await response.text(), method === 'HEAD' ? '' : 'destination');
	});
}

// Fetch §4.4 step 6.3 controls redirect modes. Node exposes the actual manual response instead of a browser's opaque-redirect response.
// https://github.com/nodejs/undici#manual-redirect
for (const throwHttpErrors of [undefined, false]) {
	test(`manual redirects are not followed with throwHttpErrors ${throwHttpErrors ?? 'default'}`, async t => {
		const server = await createHttpTestServer(t);
		const paths: string[] = [];
		server.use((request, response) => {
			paths.push(request.path);
			response.writeHead(302, {location: '/destination', 'content-type': 'text/plain'}).end('Moved');
		});

		const result = ky(`${server.url}/start`, {redirect: 'manual', throwHttpErrors, retry: 0});
		if (throwHttpErrors === undefined) {
			const error = await t.throwsAsync(result, {instanceOf: HTTPError});
			t.is(error.response.status, 302);
			t.is(error.response.headers.get('location'), '/destination');
			t.is(error.data, 'Moved');
		} else {
			const response = await result;
			t.is(response.status, 302);
			t.is(response.headers.get('location'), '/destination');
			t.false(response.redirected);
			t.is(await response.text(), 'Moved');
		}

		t.deepEqual(paths, ['/start']);
	});
}

test('redirect error mode produces a NetworkError without following or retrying', async t => {
	const server = await createHttpTestServer(t);
	const paths: string[] = [];
	server.use((request, response) => {
		paths.push(request.path);
		response.writeHead(302, {location: '/destination'}).end();
	});

	await t.throwsAsync(ky(`${server.url}/start`, {redirect: 'error', retry: 0}), {instanceOf: NetworkError});
	t.deepEqual(paths, ['/start']);
});

test('relative Location resolves against the redirecting request URL', async t => {
	// RFC 9110 §10.2.2: https://www.rfc-editor.org/rfc/rfc9110.html#section-10.2.2
	const server = await createHttpTestServer(t);
	const paths: string[] = [];
	server.get('/directory/start', (request, response) => {
		paths.push(request.url);
		response.writeHead(302, {location: '../destination?from=redirect'}).end();
	});
	server.get('/destination', (request, response) => {
		paths.push(request.url);
		response.end('arrived');
	});

	const response = await ky(`${server.url}/directory/start?original=yes`, {retry: 0});
	t.is(await response.text(), 'arrived');
	t.deepEqual(paths, ['/directory/start?original=yes', '/destination?from=redirect']);
	t.is(response.url, `${server.url}/destination?from=redirect`);
});

test('a redirect status without Location remains an HTTPError', async t => {
	// Fetch §4.5 step 4 returns the response when there is no location URL.
	const server = await createHttpTestServer(t);
	let requests = 0;
	server.get('/', (_request, response) => {
		requests++;
		response.status(302).type('text').end('No destination');
	});

	const error = await t.throwsAsync(ky(server.url, {retry: 0}), {instanceOf: HTTPError});
	t.is(error.response.status, 302);
	t.is(error.data, 'No destination');
	t.is(requests, 1);
});

import test from 'ava';
import ky, {HTTPError} from '../source/index.js';
import {createHttpTestServer} from './helpers/create-http-test-server.js';

// RFC 9110 §§9.3.2 and 8.6 allow HEAD to advertise the corresponding GET representation's length without sending content.
// https://www.rfc-editor.org/rfc/rfc9110.html#section-9.3.2
for (const status of [200, 404]) {
	test(`HEAD ${status} preserves representation headers without consuming a body`, async t => {
		const server = await createHttpTestServer(t);
		let progressCalls = 0;
		let parserCalls = 0;
		server.head('/', (_request, response) => {
			response.writeHead(status, {'content-type': 'application/json', 'content-length': '1234'}).end();
		});
		const request = ky.head(server.url, {
			retry: 0,
			onDownloadProgress() {
				progressCalls++;
			},
			parseJson() {
				parserCalls++;
				return {};
			},
		});
		if (status === 200) {
			const response = await request;
			t.is(response.headers.get('content-length'), '1234');
			t.is(await response.text(), '');
		} else {
			const error = await t.throwsAsync(request, {instanceOf: HTTPError});
			t.is(error.response.status, 404);
			t.is(error.response.headers.get('content-length'), '1234');
			t.is(error.data, undefined);
		}

		t.is(progressCalls, 0);
		t.is(parserCalls, 0);
	});
}

// RFC 9110 §§15.3.5–15.3.6 prohibit content in 204 and 205 responses.
for (const status of [204, 205]) {
	test(`${status} completes without body progress and retains response metadata`, async t => {
		const server = await createHttpTestServer(t);
		server.get('/', (_request, response) => {
			response.writeHead(status, {etag: '"version-2"'}).end();
		});
		let progressCalls = 0;
		const response = await ky(server.url, {
			onDownloadProgress() {
				progressCalls++;
			},
		});

		t.is(response.status, status);
		t.true(response.ok);
		t.is(response.headers.get('etag'), '"version-2"');
		t.is(await response.text(), '');
		t.is(progressCalls, 0);
	});
}

// A 304 has no content; Content-Length may describe the selected representation (RFC 9110 §§15.4.5 and 8.6).
for (const [condition, value] of [
	['if-none-match', '"version-1"'],
	['if-modified-since', 'Wed, 01 Jan 2025 00:00:00 GMT'],
] as const) {
	test(`conditional requests preserve ${condition} and expose bodyless 304 responses`, async t => {
		const server = await createHttpTestServer(t);
		server.get('/', (request, response) => {
			t.is(request.headers[condition], value);
			response.writeHead(304, {etag: '"version-1"', 'last-modified': 'Wed, 01 Jan 2025 00:00:00 GMT', 'content-length': '42'}).end();
		});
		let progressCalls = 0;
		const response = await ky(server.url, {
			headers: {[condition]: value},
			throwHttpErrors: false,
			onDownloadProgress() {
				progressCalls++;
			},
		});

		t.is(response.status, 304);
		t.false(response.ok);
		t.is(response.headers.get('etag'), '"version-1"');
		t.is(response.headers.get('content-length'), '42');
		t.is(await response.text(), '');
		t.is(progressCalls, 0);
	});
}

test('304 uses the default HTTP error policy without retrying or parsing absent JSON', async t => {
	const server = await createHttpTestServer(t);
	let requests = 0;
	let parserCalls = 0;
	server.get('/', (_request, response) => {
		requests++;
		response.writeHead(304, {etag: '"version-1"', 'content-type': 'application/json'}).end();
	});
	const error = await t.throwsAsync(ky(server.url, {
		headers: {'if-none-match': '"version-1"'},
		parseJson() {
			parserCalls++;
			return {};
		},
	}), {instanceOf: HTTPError});

	t.is(error.response.status, 304);
	t.is(error.data, undefined);
	t.is(requests, 1);
	t.is(parserCalls, 0);
});

// RFC 9110 §§14.4 and 15.3.7: a single-range response carries the selected bytes and their Content-Range.
test('206 preserves byte-range headers and reports progress for the partial representation', async t => {
	const server = await createHttpTestServer(t);
	server.get('/', (request, response) => {
		t.is(request.headers.range, 'bytes=2-5');
		t.is(request.headers['if-range'], '"version-1"');
		response.writeHead(206, {'content-range': 'bytes 2-5/10', 'content-length': '4'}).end('2345');
	});
	const chunks: Uint8Array[] = [];
	const transferred: number[] = [];
	const response = await ky(server.url, {
		headers: {range: 'bytes=2-5', 'if-range': '"version-1"'},
		onDownloadProgress(progress, chunk) {
			chunks.push(chunk);
			transferred.push(progress.transferredBytes);
		},
	});

	t.is(response.status, 206);
	t.true(response.ok);
	t.is(response.headers.get('content-range'), 'bytes 2-5/10');
	t.is(await response.text(), '2345');
	t.is(Buffer.concat(chunks).toString(), '2345');
	t.is(transferred.at(-1), 4);
});

test('416 preserves the unsatisfied Content-Range and error body without retrying', async t => {
	// RFC 9110 §15.5.17 permits Content-Range to indicate the current representation length.
	const server = await createHttpTestServer(t);
	let requests = 0;
	server.get('/', (request, response) => {
		requests++;
		t.is(request.headers.range, 'bytes=100-');
		response.writeHead(416, {'content-range': 'bytes */10', 'content-type': 'text/plain'}).end('Range unavailable');
	});
	const error = await t.throwsAsync(ky(server.url, {headers: {range: 'bytes=100-'}}), {instanceOf: HTTPError});

	t.is(error.response.status, 416);
	t.is(error.response.headers.get('content-range'), 'bytes */10');
	t.is(error.data, 'Range unavailable');
	t.is(requests, 1);
});

import {ReadableStream} from 'node:stream/web';
import test from 'ava';
import LeakDetector from 'jest-leak-detector';
import ky, {NetworkError, type KyInstance} from '../source/index.js';
import {createHttpTestServer} from './helpers/create-http-test-server.js';

test('shared abort signal must not cause memory leak of input', async t => {
	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		response.end('ok');
	});

	async function isKyLeaking(api: KyInstance) {
		let url: URL | undefined = new URL(`${server.url.toString()}?id=${Math.random()}`);
		const detector = new LeakDetector(url);

		await api.get(url);

		url = undefined;

		return detector.isLeaking();
	}

	const abortController = new AbortController();

	try {
		t.false(await isKyLeaking(ky.extend({})));
		t.false(await isKyLeaking(ky.extend({signal: abortController.signal})));
	} finally {
		abortController.abort();
	}
});

test('failed stream request must not cause memory leak', async t => {
	async function isStreamLeaking() {
		const stream: ReadableStream | undefined = ReadableStream.from([new TextEncoder().encode('Bell is Ringing.')]);
		const detector = new LeakDetector(stream);

		await t.throwsAsync(
			ky.post('invalid:', {
				body: stream,
			}),
			{
				instanceOf: NetworkError,
			},
		);

		return detector.isLeaking();
	}

	t.false(await isStreamLeaking());
});

