for (const [description, value, now, expected] of [
	['leap day', 'Thu, 29 Feb 2024 00:00:00 GMT', '2024-02-28T23:59:59Z', 1000],
	['space-padded asctime day', 'Sun Nov  6 08:49:37 1994', '1994-11-06T08:49:36Z', 1000],
	['past date', 'Wed, 01 Jan 2031 12:00:00 GMT', '2031-01-01T12:00:01Z', 0],
	['current date', 'Wed, 01 Jan 2031 12:00:00 GMT', '2031-01-01T12:00:00Z', 0],
] as const) {
	test.serial(`Retry-After calculates the delay for a ${description}`, t => {
		const originalNow = Date.now;
		t.teardown(() => {
			Date.now = originalNow;
		});
		Date.now = () => Date.parse(now);

		t.is(calculateRetryTimingDelay({value, allowTimestamp: false}), expected);
	});
}

test('Retry-After header names and outer whitespace are normalized by Headers', t => {
	const header = getRetryTimingHeader(new Headers({'rEtRy-AfTeR': '\t 012 \t'}));
	t.deepEqual(header, {value: '012', allowTimestamp: false});
	t.is(calculateRetryTimingDelay(header!), 12_000);
});

test('multiple Retry-After values do not become a valid delay or date', t => {
	const headers = new Headers();
	headers.append('Retry-After', '1');
	headers.append('Retry-After', '2');
	const header = getRetryTimingHeader(headers);
	t.deepEqual(header, {value: '1, 2', allowTimestamp: false});
	t.is(calculateRetryTimingDelay(header!), undefined);
});

// The "current era" cutoff used to be a hardcoded 2024-01-01, so a reset value from just before it fell below the cutoff and was read as delay seconds. A `RateLimit-Reset` of 1700000000 (November 2023) became a 54-year delay.
for (const [description, value, expected] of [
	['a November 2023 epoch as a reset in the past', '1700000000', 0],
	['a January 2023 epoch as a reset in the past', '1672531200', 0],
	['a 2001 epoch as a reset in the past', '1000000000', 0],
	['a value just below the threshold as a delay', '999999999', 999_999_999_000],
	['a small reset as a delay', '30', 30_000],
] as Array<[string, string, number]>) {
	test(`RateLimit-Reset reads ${description}`, t => {
		t.is(calculateRetryTimingDelay({value, allowTimestamp: true}), expected);
	});
}

test('Retry-After numbers are never treated as timestamps', t => {
	t.is(calculateRetryTimingDelay({value: '1700000000', allowTimestamp: false}), 1_700_000_000_000);
});

for (const [description, headers, expected] of [
	['RateLimit-Reset over X-RateLimit-Retry-After', {'RateLimit-Reset': '1', 'X-RateLimit-Retry-After': '2'}, {value: '1', allowTimestamp: true}],
	['X-RateLimit-Retry-After over X-RateLimit-Reset', {'X-RateLimit-Retry-After': '2', 'X-RateLimit-Reset': '3'}, {value: '2', allowTimestamp: false}],
	['X-RateLimit-Reset over X-Rate-Limit-Reset', {'X-RateLimit-Reset': '3', 'X-Rate-Limit-Reset': '4'}, {value: '3', allowTimestamp: true}],
] as const) {
	test(`retry timing header precedence prefers ${description}`, t => {
		t.deepEqual(getRetryTimingHeader(new Headers(headers)), expected);
	});
}

test('an empty X-RateLimit-Retry-After does not fall back to a reset header', t => {
	t.deepEqual(getRetryTimingHeader(new Headers({'X-RateLimit-Retry-After': '', 'X-RateLimit-Reset': '3'})), {value: '', allowTimestamp: false});
});

test('HTTP dates with a year below 100 are not mapped to the 1900s', t => {
	// `Date.UTC()` maps years 0-99 to 1900-1999. Such a date must still be a valid past date, not a malformed one that falls back to the normal retry delay.
	t.is(calculateRetryTimingDelay({value: 'Fri, 01 Jan 0010 00:00:00 GMT', allowTimestamp: false}), 0);
	t.is(calculateRetryTimingDelay({value: 'Fri Jan  1 00:00:00 0010', allowTimestamp: false}), 0);
});

test('RFC 850 date between 50 and 51 years in the future is interpreted as past', t => {
	// The RFC 850 century window uses the real clock, so build the date from it.
	const date = new Date();
	date.setUTCFullYear(date.getUTCFullYear() + 50, date.getUTCMonth() + 6);
	const weekday = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][date.getUTCDay()];
	const month = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][date.getUTCMonth()];
	const [day, year, time] = [
		String(date.getUTCDate()).padStart(2, '0'),
		String(date.getUTCFullYear() % 100).padStart(2, '0'),
		date.toISOString().slice(11, 19),
	];

	t.is(calculateRetryTimingDelay({value: `${weekday}, ${day}-${month}-${year} ${time} GMT`, allowTimestamp: false}), 0);
});

test.serial('asctime date with a two-digit day is parsed', t => {
	const originalNow = Date.now;
	t.teardown(() => {
		Date.now = originalNow;
	});
	Date.now = () => Date.parse('2031-01-16T12:00:00Z');

	t.is(calculateRetryTimingDelay({value: 'Thu Jan 16 12:00:02 2031', allowTimestamp: false}), 2000);
});

test('Retry-After HTTP date in year 9999 gives a finite delay', t => {
	for (const value of ['Fri, 31 Dec 9999 23:59:59 GMT', 'Fri Dec 31 23:59:59 9999']) {
		const delay = calculateRetryTimingDelay({value, allowTimestamp: false});
		t.true(Number.isFinite(delay) && delay! > 0, `value: ${value}`);
	}
});

for (const [description, value] of [
	['IMF-fixdate', 'Wed, 31 Dec 2031 23:59:60 GMT'],
	['asctime', 'Wed Dec 31 23:59:60 2031'],
] as const) {
	test.serial(`Retry-After ${description} leap second at the end of a year resolves to the start of the next year`, t => {
		const originalNow = Date.now;
		t.teardown(() => {
			Date.now = originalNow;
		});
		Date.now = () => Date.parse('2031-12-31T23:59:59Z');

		t.is(calculateRetryTimingDelay({value, allowTimestamp: false}), 1000);
	});
}

// `Number()` of a long digit string overflows to `Infinity` rather than `NaN`, so the delay is unbounded but still a usable number for Ky to cap.
test('Retry-After with more digits than a number can hold gives an infinite delay', t => {
	t.is(calculateRetryTimingDelay({value: '9'.repeat(400), allowTimestamp: false}), Number.POSITIVE_INFINITY);
});

import test from 'ava';
import ky from '../source/index.js';
import {createHttpTestServer} from './helpers/create-http-test-server.js';

// Retries right away, so the tests do not wait for a backoff.
const retryOnce = {limit: 1, delay: () => 0};

// A `fetch` that always answers `503` and counts its calls.
const createUnavailableFetch = () => {
	const state = {
		calls: 0,
		async fetch() {
			state.calls++;
			return new Response('retry', {status: 503});
		},
	};

	return state;
};

test('beforeRetry can turn off upload progress without losing the body', async t => {
	let attempts = 0;
	const progressAttempts: number[] = [];
	const response = await ky.put('https://example.com', {
		body: 'payload',
		retry: retryOnce,
		onUploadProgress() {
			progressAttempts.push(attempts);
		},
		async fetch(request) {
			attempts++;
			t.is(await request.text(), 'payload');
			if (attempts === 1) {
				throw new TypeError('Failed to fetch');
			}

			return new Response('ok');
		},
		hooks: {
			beforeRetry: [() => ({options: {onUploadProgress: undefined}})],
		},
	});

	t.is(await response.text(), 'ok');
	t.is(attempts, 2);
	t.deepEqual(progressAttempts, [1]);
});

test('beforeRetry can turn on upload progress without losing the body', async t => {
	let attempts = 0;
	const progressAttempts: number[] = [];
	const response = await ky.put('https://example.com', {
		body: 'payload',
		retry: retryOnce,
		async fetch(request) {
			attempts++;
			t.is(await request.text(), 'payload');
			if (attempts === 1) {
				throw new TypeError('Failed to fetch');
			}

			return new Response('ok');
		},
		hooks: {
			beforeRetry: [() => ({
				options: {
					onUploadProgress() {
						progressAttempts.push(attempts);
					},
				},
			})],
		},
	});

	t.is(await response.text(), 'ok');
	t.deepEqual(progressAttempts, [2]);
});

test('beforeRetry options apply to later retries and later hooks', async t => {
	let attempts = 0;
	let originalProgressCalls = 0;
	let replacementProgressCalls = 0;
	const originalProgress = () => {
		originalProgressCalls++;
	};

	const replacementProgress = () => {
		replacementProgressCalls++;
	};

	const seenProgress: unknown[] = [];
	const text = await ky('https://example.com', {
		onDownloadProgress: originalProgress,
		retry: {...retryOnce, limit: 2},
		async fetch() {
			attempts++;
			return new Response('ok', {status: attempts < 3 ? 503 : 200});
		},
		hooks: {
			beforeRetry: [
				({options, retryCount}) => {
					seenProgress.push(options.onDownloadProgress);
					if (retryCount === 1) {
						return {options: {onDownloadProgress: replacementProgress}};
					}
				},
				({options}) => {
					t.is(options.onDownloadProgress, replacementProgress);
				},
			],
		},
	}).text();

	t.is(text, 'ok');
	t.is(attempts, 3);
	t.deepEqual(seenProgress, [originalProgress, replacementProgress]);
	t.is(originalProgressCalls, 0);
	t.true(replacementProgressCalls > 0);
});

test('beforeRetry can change fetch and throwHttpErrors', async t => {
	const unavailable = createUnavailableFetch();
	let replacementFetchCalls = 0;
	const response = await ky('https://example.com', {
		retry: retryOnce,
		fetch: unavailable.fetch,
		hooks: {
			beforeRetry: [() => ({
				options: {
					async fetch() {
						replacementFetchCalls++;
						return new Response('still failing', {status: 500});
					},
					throwHttpErrors: false,
				},
			})],
		},
	});

	t.is(response.status, 500);
	t.is(unavailable.calls, 1);
	t.is(replacementFetchCalls, 1);
});

test('beforeRetry can change throwHttpErrors to a function', async t => {
	const unavailable = createUnavailableFetch();
	const statuses: number[] = [];
	const response = await ky('https://example.com', {
		retry: retryOnce,
		fetch: unavailable.fetch,
		hooks: {
			beforeRetry: [() => ({
				options: {
					throwHttpErrors(status) {
						statuses.push(status);
						return false;
					},
				},
			})],
		},
	});

	t.is(response.status, 503);
	t.deepEqual(statuses, [503]);
});

test('beforeRetry can change the timeout', async t => {
	let attempts = 0;
	const response = await ky('https://example.com', {
		timeout: 10,
		retry: {...retryOnce, retryOnTimeout: true},
		async fetch(request) {
			attempts++;
			await new Promise(resolve => {
				setTimeout(resolve, 50);
			});
			request.signal.throwIfAborted();
			return new Response('ok');
		},
		hooks: {
			beforeRetry: [() => ({options: {timeout: 1000}})],
		},
	});

	t.is(await response.text(), 'ok');
	t.is(attempts, 2);
});

test('beforeRetry options apply to a response returned by a later hook', async t => {
	const unavailable = createUnavailableFetch();
	const response = await ky('https://example.com', {
		retry: retryOnce,
		fetch: unavailable.fetch,
		hooks: {
			beforeRetry: [
				() => ({options: {throwHttpErrors: false}}),
				() => new Response('from hook', {status: 500}),
			],
		},
	});

	t.is(response.status, 500);
	t.is(await response.text(), 'from hook');
	t.is(unavailable.calls, 1);
});

test('beforeRetry `undefined` restores the global fetch', async t => {
	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		response.end('native');
	});

	const unavailable = createUnavailableFetch();
	const result = await ky(server.url, {
		retry: retryOnce,
		fetch: unavailable.fetch,
		hooks: {beforeRetry: [() => ({options: {fetch: undefined}})]},
	}).text();

	t.is(result, 'native');
	t.is(unavailable.calls, 1);
});

test('beforeRetry `undefined` restores Ky\'s default rather than the instance value', async t => {
	let attempts = 0;
	const api = ky.create({
		throwHttpErrors: false,
		retry: retryOnce,
		async fetch() {
			attempts++;
			if (attempts === 1) {
				throw new TypeError('Failed to fetch');
			}

			return new Response('failed', {status: 500});
		},
	});

	await t.throwsAsync(api('https://example.com', {
		hooks: {beforeRetry: [() => ({options: {throwHttpErrors: undefined}})]},
	}), {name: 'HTTPError'});
	t.is(attempts, 2);
});

test('beforeRetry options do not leak into other requests from the same instance', async t => {
	let progressCalls = 0;
	const attempts = new Map<string, number>();
	const api = ky.create({
		retry: retryOnce,
		onUploadProgress() {
			progressCalls++;
		},
		async fetch(request) {
			const count = (attempts.get(request.url) ?? 0) + 1;
			attempts.set(request.url, count);
			await request.text();
			return new Response('ok', {status: count === 1 ? 503 : 200});
		},
	});

	await api.put('https://example.com/changed', {
		body: 'payload',
		hooks: {beforeRetry: [() => ({options: {onUploadProgress: undefined}})]},
	});
	// A small body reports progress once per streamed attempt.
	t.is(progressCalls, 1);

	await api.put('https://example.com/unchanged', {body: 'payload'});
	t.is(progressCalls, 3);
});

test('beforeRetry options do not reset the retry limit', async t => {
	const unavailable = createUnavailableFetch();
	await t.throwsAsync(ky('https://example.com', {
		retry: {...retryOnce, limit: 2},
		fetch: unavailable.fetch,
		hooks: {beforeRetry: [() => ({options: {timeout: false}})]},
	}), {name: 'HTTPError'});

	t.is(unavailable.calls, 3);
});

const notAnOptionsObject = 'The `options` returned from a `beforeRetry` hook must be an object';

import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import ky, {
	HTTPError,
	NetworkError,
	ForceRetryError,
	SchemaValidationError,
	TimeoutError,
	isKyError,
	isHTTPError,
	isNetworkError,
	isTimeoutError,
	isForceRetryError,
} from '../source/index.js';

test('error names can be customized without changing instance type guards', async t => {
	const request = new Request('https://example.com');
	const httpError = await t.throwsAsync(ky(request, {
		retry: 0,
		fetch: async () => new Response('Forbidden', {status: 403}),
	}), {instanceOf: HTTPError});

	for (const [error, guard] of [
		[httpError, isHTTPError],
		[new NetworkError(request), isNetworkError],
		[new TimeoutError(request), isTimeoutError],
		[new ForceRetryError(), isForceRetryError],
	] as const) {
		t.is(error.name, error.constructor.name);
		error.name = 'CustomError';
		t.true(error.toString().startsWith('CustomError: '));
		t.true(guard(error));
		t.true(isKyError(error));
	}

	const validationError = new SchemaValidationError([{message: 'Invalid response'}]);
	t.is(validationError.name, 'SchemaValidationError');
	validationError.name = 'InvalidResponseError';
	t.true(validationError.toString().startsWith('InvalidResponseError: '));
	t.true(validationError instanceof SchemaValidationError);
	t.false(isKyError(validationError));
});

test('AbortSignal.timeout errors are not Ky errors', async t => {
	const signal = AbortSignal.timeout(0);
	await delay(10);

	t.true(signal.aborted);
	t.true(signal.reason instanceof DOMException);
	t.is(signal.reason.name, 'TimeoutError');
	t.false(isTimeoutError(signal.reason));
	t.false(isKyError(signal.reason));
});

test('Ky timeout errors are recognized', t => {
	const error = new TimeoutError(new Request('https://example.com'));

	t.true(isTimeoutError(error));
	t.true(isKyError(error));
});

for (const [name, guard] of [
	['HTTPError', isHTTPError],
	['NetworkError', isNetworkError],
	['TimeoutError', isTimeoutError],
	['ForceRetryError', isForceRetryError],
] as const) {
	test(`${name} guard rejects unrelated errors with the same name`, t => {
		const error = new Error('Not from Ky');
		error.name = name;

		t.false(guard(error));
		t.false(isKyError(error));
	});

	test(`${name} guard recognizes branded errors from another Ky constructor`, t => {
		const error = Object.assign(new Error('From another Ky constructor'), {
			name,
			isKyError: true,
		});

		t.true(guard(error));
		t.true(isKyError(error));
	});
}

// Ky ships `isForceRetryError()` for cross-realm use, but its own retry logic used `instanceof`, so a `ForceRetryError` from a second copy of Ky was silently never retried.
test('a branded ForceRetryError from another Ky copy still forces a retry', async t => {
	let attempts = 0;
	const branded = Object.assign(new Error('From another Ky constructor'), {
		name: 'ForceRetryError',
		isKyError: true,
	});

	const text = await ky('https://example.com', {
		async fetch() {
			attempts++;
			if (attempts === 1) {
				throw branded;
			}

			return new Response('retried');
		},
		retry: {limit: 1, delay: () => 0},
	}).text();

	t.is(attempts, 2);
	t.is(text, 'retried');
});

import test from 'ava';
import ky, {type ResponsePromise} from '../source/index.js';

const okFetch = async () => new Response('ok');

// `timeout` and `totalTimeout` are documented as milliseconds or `false`. Anything else used to be passed straight to `setTimeout()`, which clamps it to ~1ms, or was silently ignored, so the request never got the timeout the caller asked for. `null` is not accepted either, so it is reported rather than selecting the default.
test('rejects non-numeric and negative `timeout` values', async t => {
	for (const timeout of ['1000', Number.NaN, -1, -0.5, {}, null] as unknown[]) {
		// eslint-disable-next-line no-await-in-loop
		await t.throwsAsync(ky('https://example.com', {timeout: timeout as never, fetch: okFetch}),
			{
				name: 'TypeError',
				message: 'The `timeout` option must be a non-negative number or `false`',
			},
			`timeout: ${JSON.stringify(timeout)}`,
		);
	}
});

test('rejects non-numeric and negative `totalTimeout` values', async t => {
	for (const totalTimeout of ['1000', Number.NaN, -1, -0.5, {}, null] as unknown[]) {
		// eslint-disable-next-line no-await-in-loop
		await t.throwsAsync(ky('https://example.com', {totalTimeout: totalTimeout as never, fetch: okFetch}),
			{
				name: 'TypeError',
				message: 'The `totalTimeout` option must be a non-negative number or `false`',
			},
			`totalTimeout: ${JSON.stringify(totalTimeout)}`,
		);
	}
});

test('treats an `undefined` timeout as absent', async t => {
	t.is(await ky('https://example.com', {timeout: undefined, totalTimeout: undefined, fetch: okFetch}).text(), 'ok');
});

test('rejects `timeout` and `totalTimeout` above the maximum safe value', async t => {
	for (const option of ['timeout', 'totalTimeout'] as const) {
		for (const value of [2_147_483_648, Number.POSITIVE_INFINITY]) {
			// eslint-disable-next-line no-await-in-loop
			await t.throwsAsync(ky('https://example.com', {[option]: value, fetch: okFetch}),
				{
					instanceOf: RangeError,
					message: `The \`${option}\` option cannot be greater than 2147483647`,
				},
				`${option}: ${value}`,
			);
		}
	}
});

test('accepts `false`, `0` and non-negative numbers for the timeout options', async t => {
	t.is(await ky('https://example.com', {timeout: false, totalTimeout: false, fetch: okFetch}).text(), 'ok');
	t.is(await ky('https://example.com', {timeout: 0, totalTimeout: 5000, fetch: async () => new Response('a')}).text(), 'a');
});

test('rejects invalid timeout values set from an `init` hook', async t => {
	await t.throwsAsync(ky('https://example.com', {
		fetch: okFetch,
		hooks: {
			init: [options => {
				options.timeout = 'soon' as never;
			}],
		},
	}), {
		name: 'TypeError',
		message: 'The `timeout` option must be a non-negative number or `false`',
	});
});

// These callbacks are called directly, so a non-function value surfaced as a runtime error naming Ky's own internals (`this[#options].stringifyJson`, `initHookOptions.parseJson`) instead of the option the user set, and only once the request had already been built. The constructor calls `stringifyJson` itself, so that one has to be checked before anything else happens.
test('rejects non-function callback options', async t => {
	for (const [key, value] of [
		['parseJson', 'x'],
		['stringifyJson', 5],
		['fetch', 'x'],
		['fetch', null],
		['onDownloadProgress', 'x'],
		['onUploadProgress', 'x'],
	] as Array<[string, unknown]>) {
		const options: Record<string, unknown> = {[key]: value};

		// eslint-disable-next-line no-await-in-loop
		await t.throwsAsync(ky('https://example.com', options as never), {
			name: 'TypeError',
			message: `The \`${key}\` option must be a function`,
		}, `${key}: ${JSON.stringify(value)}`);
	}
});

test('rejects a non-function `stringifyJson` before it is called', async t => {
	await t.throwsAsync(ky.post('https://example.com', {
		json: {a: 1},
		stringifyJson: 'nope' as never,
		fetch: okFetch,
	}), {
		name: 'TypeError',
		message: 'The `stringifyJson` option must be a function',
	});
});

test('rejects a `throwHttpErrors` value that is neither a boolean nor a function', async t => {
	for (const value of ['yes', 1, {}, null] as unknown[]) {
		const options: Record<string, unknown> = {
			throwHttpErrors: value,
			fetch: async () => new Response('server error', {status: 500}),
		};

		// eslint-disable-next-line no-await-in-loop
		await t.throwsAsync(ky('https://example.com', options as never), {
			name: 'TypeError',
			message: 'The `throwHttpErrors` option must be a boolean or a function',
		}, `throwHttpErrors: ${JSON.stringify(value)}`);
	}
});

test('accepts a valid `throwHttpErrors` function', async t => {
	const options: Record<string, unknown> = {
		throwHttpErrors: (status: number) => status === 404,
		fetch: async () => new Response('server error', {status: 500}),
	};

	t.is(await ky('https://example.com', options as never).text(), 'server error');
});

// The `input` type check ran after the options were built, so a nullish input dereferenced `.headers` first and reported an internal TypeError instead of the option the caller got wrong.
test('a nullish or non-string `input` reports the input error', async t => {
	for (const input of [null, undefined, 5, {}, true] as unknown[]) {
		// eslint-disable-next-line no-await-in-loop
		await t.throwsAsync(ky(input as never, {fetch: okFetch}), {
			name: 'TypeError',
			message: '`input` must be a string, URL, or Request',
		}, `input: ${String(input)}`);
	}
});

// `onDownloadProgress` was type-checked at the very end of the pipeline, so an invalid value ran the whole request and only then reported the typo, leaving the response body with nobody able to release it.
test('rejects a non-function `onDownloadProgress` before the request is sent', async t => {
	let fetchCalled = false;
	let beforeRequestCalls = 0;

	await t.throwsAsync(ky('https://example.com', {
		onDownloadProgress: 'x' as never,
		retry: 0,
		hooks: {
			beforeRequest: [() => {
				beforeRequestCalls++;
			}],
		},
		async fetch() {
			fetchCalled = true;
			return new Response('ok');
		},
	}), {
		name: 'TypeError',
		message: 'The `onDownloadProgress` option must be a function',
	});

	t.false(fetchCalled);
	t.is(beforeRequestCalls, 0);
});

// `ky()` returns a promise, so errors while setting up the request reject it, the same way `fetch()` reports them, instead of also throwing synchronously.
test('setup errors reject the returned promise and every body method', async t => {
	const setups: Array<[string, unknown, Record<string, unknown>]> = [
		['invalid option', 'https://example.com', {timeout: -1}],
		['invalid input', 42, {}],
		['invalid merged option', 'https://example.com', {hooks: 'none'}],
		['throwing `init` hook', 'https://example.com', {
			hooks: {
				init: [() => {
					throw new Error('init failed');
				}],
			},
		}],
	];

	for (const [label, input, options] of setups) {
		let responsePromise: ResponsePromise | undefined;
		t.notThrows(() => {
			responsePromise = ky(input as never, {...options, fetch: okFetch});
		}, `${label}`);

		// eslint-disable-next-line no-await-in-loop
		const error = await t.throwsAsync(responsePromise!, undefined, `${label}`);

		for (const method of ['json', 'text', 'arrayBuffer', 'blob', 'formData'] as const) {
			// eslint-disable-next-line no-await-in-loop
			t.is(await t.throwsAsync(responsePromise![method]()), error, `${label}: ${method}`);
		}
	}
});

test('setup errors also reject `.bytes()` with the same error', async t => {
	if (typeof (Response.prototype as unknown as {bytes?: unknown}).bytes !== 'function') {
		t.pass();
		return;
	}

	const responsePromise = ky('https://example.com', {timeout: -1, fetch: okFetch});
	const error = await t.throwsAsync(responsePromise);

	t.is(await t.throwsAsync(responsePromise.bytes()), error);
});

// Option merging only checked `hooks` when it was an object, and replaced an invalid `retry`, so a later layer hid a `null` or another bad shape instead of reporting it.
test('rejects a bad `hooks` or `retry` while merging, before a later layer can hide it', async t => {
	for (const hooks of [null, 'nope', []] as unknown[]) {
		t.throws(() => ky.create({hooks: hooks as never}), {
			instanceOf: TypeError,
			message: 'The `hooks` option must be an object',
		}, `hooks: ${JSON.stringify(hooks)}`);
	}

	for (const retry of [null, 'nope', []] as unknown[]) {
		t.throws(() => ky.create({retry: retry as never}), {
			instanceOf: TypeError,
			message: '`retry` must be a number or an object',
		}, `retry: ${JSON.stringify(retry)}`);
	}

	await t.throwsAsync(ky.extend({fetch: okFetch})('https://example.com', {hooks: null as never}), {
		name: 'TypeError',
		message: 'The `hooks` option must be an object',
	});
});

test('rejects `null` for `referrer` and `referrerPolicy`', async t => {
	for (const key of ['referrer', 'referrerPolicy']) {
		// eslint-disable-next-line no-await-in-loop
		await t.throwsAsync(ky('https://example.com', {[key]: null, fetch: okFetch} as never), {
			name: 'TypeError',
			message: `The \`${key}\` option must not be \`null\`. Use \`undefined\` to clear it.`,
		});
	}
});

test('rejects a `retry.retryOnTimeout` that is not a boolean', async t => {
	for (const retryOnTimeout of [null, 'false', 0] as unknown[]) {
		// eslint-disable-next-line no-await-in-loop
		await t.throwsAsync(ky('https://example.com', {retry: {retryOnTimeout: retryOnTimeout as never}, fetch: okFetch}), {
			name: 'TypeError',
			message: '`retry.retryOnTimeout` must be a boolean',
		}, `retryOnTimeout: ${JSON.stringify(retryOnTimeout)}`);
	}
});

import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import {promiseWithTimeout} from './helpers/with-page.js';

test('promiseWithTimeout returns result when promise resolves in time', async t => {
	const result = await promiseWithTimeout(
		Promise.resolve('ok'),
		1000,
		'should not time out',
	);

	t.is(result, 'ok');
});

test('promiseWithTimeout throws when promise does not resolve in time', async t => {
	const startTime = Date.now();

	const error = await t.throwsAsync(
		promiseWithTimeout(
			delay(100),
			10,
			'timed out',
		),
	);

	t.is(error?.message, 'timed out');
	t.true(Date.now() - startTime < 100);
});

